180	func (s *APIV1Service) UpdateInstanceSetting(ctx context.Context, request *v1pb.UpdateInstanceSettingRequest) (*v1pb.InstanceSetting, error) {
181		user, err := s.fetchCurrentUser(ctx)
182		if err != nil {
183			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
184		}
185		if user == nil {
186			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
187		}
188		if user.Role != store.RoleAdmin {
189			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
190		}
191		if request.Setting == nil {
192			return nil, status.Errorf(codes.InvalidArgument, "instance setting is required")
193		}
194		settingKeyString, err := ExtractInstanceSettingKeyFromName(request.Setting.Name)
195		if err != nil {
196			return nil, status.Errorf(codes.InvalidArgument, "invalid instance setting name: %v", err)
197		}
198		settingKey := storepb.InstanceSettingKey(storepb.InstanceSettingKey_value[settingKeyString])
199		if s.Store.IsInstanceSettingDeploymentConfigured(settingKey) {
200			return nil, status.Errorf(codes.FailedPrecondition, "instance setting %q is configured by the deployment", settingKeyString)
201		}
202	
203		// TODO: Apply update_mask if specified
204		_ = request.UpdateMask
205	
206		if err := validateInstanceSetting(request.Setting); err != nil {
207			return nil, status.Errorf(codes.InvalidArgument, "invalid instance setting: %v", err)
208		}
209	
210		updateSetting := convertInstanceSettingToStore(request.Setting)
211	
212		// Preserve write-only credential fields when the caller sends an empty value.
213		// An empty string means "no change", not "clear the credential".
214		switch updateSetting.Key {
215		case storepb.InstanceSettingKey_NOTIFICATION:
216			if notif := updateSetting.GetNotificationSetting(); notif != nil && notif.Email != nil && notif.Email.SmtpPassword == "" {
217				existing, err := s.Store.GetInstanceNotificationSetting(ctx)
218				if err == nil && existing != nil && existing.Email != nil {
219					if existing.Email.SmtpPassword != "" && !sameSMTPConnectionIdentity(notif.Email, existing.Email) {
220						return nil, status.Errorf(codes.InvalidArgument, "smtp password is required when changing SMTP host, port, username, or encryption settings")
221					}
222					notif.Email.SmtpPassword = existing.Email.SmtpPassword
223				}
224			}
225		case storepb.InstanceSettingKey_STORAGE:
226			if storage := updateSetting.GetStorageSetting(); storage != nil && storage.S3Config != nil && storage.S3Config.AccessKeySecret == "" {
227				existing, err := s.Store.GetInstanceStorageSetting(ctx)
228				if err == nil && existing != nil && existing.S3Config != nil {
229					storage.S3Config.AccessKeySecret = existing.S3Config.AccessKeySecret
230				}
231			}
232		case storepb.InstanceSettingKey_AI:
233			if err := s.prepareInstanceAISettingForUpdate(ctx, updateSetting.GetAiSetting()); err != nil {
234				return nil, status.Errorf(codes.InvalidArgument, "invalid AI setting: %v", err)
235			}
236		default:
237			// No credential preservation needed for other setting types.
238		}
239	
240		var instanceSetting *storepb.InstanceSetting
241		if updateSetting.Key == storepb.InstanceSettingKey_GENERAL {
242			instanceSetting, err = s.Store.UpsertInstanceGeneralSettingSafely(ctx, updateSetting)
243		} else {
244			instanceSetting, err = s.Store.UpsertInstanceSetting(ctx, updateSetting)
245		}
246		if err != nil {
247			if errors.Is(err, store.ErrUnsafeAuthenticationConfiguration) {
248				return nil, status.Error(codes.FailedPrecondition, err.Error())
249			}
250			return nil, status.Errorf(codes.Internal, "failed to upsert instance setting: %v", err)
251		}
252	
253		return convertInstanceSettingFromStore(instanceSetting), nil
254	}
