292	func (s *APIV1Service) resolveTestEmailSetting(ctx context.Context, requestEmail *v1pb.InstanceSetting_NotificationSetting_EmailSetting) (*storepb.InstanceNotificationSetting_EmailSetting, error) {
293		if requestEmail == nil {
294			existing, err := s.Store.GetInstanceNotificationSetting(ctx)
295			if err != nil {
296				return nil, status.Errorf(codes.Internal, "failed to get notification setting: %v", err)
297			}
298			return existing.GetEmail(), nil
299		}
300	
301		emailSetting := convertInstanceNotificationSettingToStore(&v1pb.InstanceSetting_NotificationSetting{Email: requestEmail}).GetEmail()
302		if emailSetting.SmtpPassword != "" {
303			return emailSetting, nil
304		}
305	
306		existing, err := s.Store.GetInstanceNotificationSetting(ctx)
307		if err != nil {
308			return nil, status.Errorf(codes.Internal, "failed to get notification setting: %v", err)
309		}
310		existingEmail := existing.GetEmail()
311		if existingEmail == nil || existingEmail.SmtpPassword == "" {
312			return emailSetting, nil
313		}
314		if sameSMTPConnectionIdentity(emailSetting, existingEmail) {
315			emailSetting.SmtpPassword = existingEmail.SmtpPassword
316			return emailSetting, nil
317		}
318		return nil, status.Errorf(codes.InvalidArgument, "smtp password is required when changing SMTP host, port, username, or encryption settings")
319	}
320	
321	func sameSMTPConnectionIdentity(setting, existing *storepb.InstanceNotificationSetting_EmailSetting) bool {
322		if setting == nil || existing == nil {
323			return false
324		}
325		return strings.TrimSpace(setting.SmtpHost) == strings.TrimSpace(existing.SmtpHost) &&
326			setting.SmtpPort == existing.SmtpPort &&
327			strings.TrimSpace(setting.SmtpUsername) == strings.TrimSpace(existing.SmtpUsername) &&
328			setting.UseTls == existing.UseTls &&
329			setting.UseSsl == existing.UseSsl
330	}
